from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'configuration'
CATALOG = [{'id': 'config-worker-pool', 'concept': 'cpu-worker-pool-sizing-config', 'domain': 'software-engineering', 'subdomain': 'concurrency', 'difficulty': 'intermediate', 'question': 'A CPU-bound service exposes a configurable worker count and is currently set to 256 workers on an 8-core machine. Give a safer configuration approach.', 'answer': 'Start from measured CPU capacity and workload behavior rather than an arbitrarily large number. For CPU-bound work, test worker counts near the available CPU concurrency and observe throughput, run-queue length, context switches, and tail latency. Keep the setting bounded and documented. If tasks block on I/O, a higher count may be justified, but it should still come from measured wait/compute behavior rather than the assumption that more workers always increase throughput.', 'verification_details': 'Must size from measured workload/CPU behavior, distinguish CPU-bound from blocking work, and reject unbounded high worker counts as a default.', 'tags': ['thread-pool', 'workers', 'cpu', 'configuration'], 'verification_method': 'rubric'}, {'id': 'config-core-dump-limit', 'concept': 'core-dump-size-limit-config', 'domain': 'systems-programming', 'subdomain': 'diagnostics', 'difficulty': 'intermediate', 'question': 'A production service is expected to generate a core dump on crash, but no core is produced. The binary itself has not disabled dumping. What configuration should be checked?', 'answer': "Check the process's core-size resource limit (`RLIMIT_CORE`/shell or service-manager equivalent), the system's core-pattern/handler configuration, filesystem permissions and free space, and service sandboxing settings that may redirect or prevent dump creation. Under systemd, also inspect the effective unit limits and coredump service policy. Setting only a debugger flag inside the program cannot override an external zero core-size limit.", 'verification_details': 'Must inspect RLIMIT_CORE plus system core handler/path/permissions and service-manager policy rather than assuming the application alone controls dump creation.', 'tags': ['core-dump', 'rlimit', 'diagnostics', 'linux'], 'verification_method': 'rubric'}, {'id': 'config-thp-policy', 'concept': 'transparent-hugepage-policy-config', 'domain': 'operating-systems', 'subdomain': 'virtual-memory', 'difficulty': 'advanced', 'question': 'A latency-sensitive workload shows occasional long allocation/compaction stalls. Transparent Huge Pages are enabled aggressively. How should THP policy be evaluated rather than disabled blindly?', 'answer': 'Measure huge-page allocation success, compaction/reclaim stalls, page-fault latency, TLB behavior, and application tail latency under the current policy. Compare controlled runs with a less aggressive or madvise-style policy for the same workload. THP can reduce TLB pressure for large contiguous working sets but can add allocation/compaction cost. Choose a policy based on the workload and kernel behavior rather than assuming THP is universally good or bad.', 'verification_details': 'Must compare THP policies with stall/TLB/latency evidence and state the tradeoff between translation efficiency and allocation/compaction cost.', 'tags': ['thp', 'hugepage', 'latency', 'configuration'], 'verification_method': 'rubric'}, {'id': 'config-journald-rate-limit', 'concept': 'journald-rate-limit-config', 'domain': 'linux-infrastructure', 'subdomain': 'logging', 'difficulty': 'intermediate', 'question': 'During an incident a service emits thousands of repeated log lines per second, and important messages are suppressed by journald rate limiting. Configure a safer logging strategy without simply removing all limits.', 'answer': 'Keep rate limiting as a protection against runaway logging, but tune the journald interval/burst to the expected incident volume and reduce repetition at the application source with aggregation or sampled diagnostics. Ensure critical health/error signals use a path or severity policy that remains observable. Monitor dropped/suppressed counts. Disabling limits entirely can let one broken service consume disk and I/O resources.', 'verification_details': 'Must preserve bounded logging, tune rate/burst with application-side suppression/aggregation, keep critical signals observable, and avoid unlimited logging.', 'tags': ['journald', 'rate-limit', 'logging', 'operations'], 'verification_method': 'rubric'}, {'id': 'config-nofile-headroom', 'concept': 'service-nofile-headroom-config', 'domain': 'linux-infrastructure', 'subdomain': 'resource-limits', 'difficulty': 'advanced', 'question': 'A proxy is configured for 50,000 concurrent connections but its service unit inherits a file-descriptor limit of 16,384. What should the limit calculation include?', 'answer': 'Estimate descriptors per connection plus fixed and transient overhead: listeners, upstream sockets, logs, DNS, metrics, pipes/eventfds, temporary files, accepted-but-not-yet-accounted sockets, and operational reserve. Set the service-manager limit above the modeled peak with headroom, while also checking system-wide limits. Validate under load by measuring actual descriptor usage. A connection count cannot be mapped to one descriptor each when the proxy may hold both downstream and upstream sockets.', 'verification_details': 'Must include per-connection and fixed/transient descriptor costs, operational headroom, system/unit limits, and load validation.', 'tags': ['nofile', 'proxy', 'file-descriptor', 'capacity'], 'verification_method': 'rubric'}, {'id': 'config-watchdog-boot-time', 'concept': 'embedded-watchdog-boot-timeout-config', 'domain': 'embedded-systems', 'subdomain': 'watchdog', 'difficulty': 'advanced', 'question': 'An MCU watchdog timeout is shorter than the worst-case firmware startup time after a cold boot, causing resets during legitimate initialization. Configure the watchdog without losing hang protection.', 'answer': 'Measure worst-case startup phases across voltage/temperature/storage conditions. Use a platform-supported startup/boot watchdog strategy: select an initial timeout that safely covers verified boot initialization, feed only at known progress points, then tighten to the normal runtime timeout once the system reaches its health milestone. Do not simply disable the watchdog during startup if startup can itself hang. If hardware supports windowed or staged watchdogs, configure them consistently with those phases.', 'verification_details': 'Must base timeout on measured worst-case boot, retain progress-based watchdog protection during startup, and transition to a tighter runtime policy.', 'tags': ['embedded', 'watchdog', 'boot', 'timeout'], 'verification_method': 'rubric'}, {'id': 'config-tcp-keepalive', 'concept': 'tcp-keepalive-failure-detection-config', 'domain': 'networking', 'subdomain': 'tcp', 'difficulty': 'advanced', 'question': 'A long-lived TCP control connection may sit idle for hours, but the application needs dead peers detected within several minutes. Configure keepalive behavior without treating it as an application heartbeat.', 'answer': 'Enable TCP keepalive on the socket and choose idle/probe interval/probe-count values whose failure-detection window fits the operational requirement and network policy. Verify intermediaries do not silently drop the idle flow earlier. Keepalive only establishes that the transport peer responds; it does not prove the remote application is healthy or making semantic progress. Use an application heartbeat when that stronger property is required.', 'verification_details': 'Must configure idle/interval/count from the desired detection window, account for intermediaries, and distinguish transport liveness from application health.', 'tags': ['tcp', 'keepalive', 'liveness', 'configuration'], 'verification_method': 'rubric'}, {'id': 'config-election-timeout', 'concept': 'distributed-election-timeout-range', 'domain': 'distributed-systems', 'subdomain': 'consensus', 'difficulty': 'expert', 'question': 'A consensus cluster repeatedly triggers elections during normal latency spikes because its election timeout is close to routine heartbeat delay. How should the timeout range be configured?', 'answer': 'Measure heartbeat/round-trip latency distribution, scheduling pauses, storage stalls, and expected failure-detection objectives. Configure election timeouts with margin above normal worst-case heartbeat delay and randomize them across nodes so candidates do not repeatedly time out together. Longer timeouts reduce false elections but increase genuine failure-detection time, so the choice is an availability/stability tradeoff. Validate with fault injection and realistic pause/latency distributions.', 'verification_details': 'Must set randomized election timeouts from measured delay/pause distributions, explain false-election versus failure-detection tradeoff, and validate under faults.', 'tags': ['consensus', 'election-timeout', 'heartbeat', 'configuration'], 'verification_method': 'rubric'}, {'id': 'config-tls-min-version', 'concept': 'tls-minimum-version-policy', 'domain': 'secure-engineering', 'subdomain': 'tls', 'difficulty': 'advanced', 'question': 'An internal service still accepts legacy TLS versions for compatibility, although all known clients support modern TLS. Define a safe configuration-change process.', 'answer': 'Inventory actual client protocol/cipher usage first, then set a minimum TLS version consistent with organizational policy and supported clients. Stage the change, monitor handshake failures, and retain a rollback path for unidentified dependencies. Prefer current library defaults/policy suites over hand-curating fragile cipher lists unless there is a specific requirement. Do not disable certificate verification or weaken other controls to compensate for client incompatibility.', 'verification_details': 'Must inventory client capability, stage/monitor the minimum-version change, preserve rollback, and reject weakening identity verification as a compatibility workaround.', 'tags': ['tls', 'protocol-version', 'hardening', 'configuration'], 'verification_method': 'rubric'}, {'id': 'config-feature-kill-switch', 'concept': 'feature-kill-switch-config', 'domain': 'engineering-reasoning', 'subdomain': 'operational-safety', 'difficulty': 'advanced', 'question': 'A risky optional feature depends on a new backend. Configure rollout controls so operators can disable it quickly during an incident without redeploying the whole service.', 'answer': 'Use a versioned feature flag/kill switch with a safe default, scoped rollout, authenticated change path, audit history, and rapid propagation semantics that are understood and tested. The service should fail safely when flag configuration is unavailable and should expose the active flag version/state. Avoid making correctness-critical invariants depend on a mutable flag unless both states are explicitly supported. Exercise disable/reenable procedures before production rollout.', 'verification_details': 'Must provide authenticated/audited fast disable, safe defaults/failure behavior, observable active state, and tested rollout/rollback semantics.', 'tags': ['feature-flag', 'kill-switch', 'rollout', 'operations'], 'verification_method': 'rubric'}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]
BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        PURPOSE,
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
